import React from 'react';
import {RouteComponentProps, Link, withRouter} from "react-router-dom";
import {MatchProps} from "../interfaces";
import cx from 'classnames';
//import '../mdbootstrap/js/vendor/jarallax';
// @ts-ignore
import {jarallax} from 'jarallax';
import _T from '../lang';

import bs from "../styles/styles.module.scss"
import "../styles/styles.scss";
import homeStyle from './home.module.css';
import * as Waves from "../mdbootstrap/js/vendor/waves";

import Footer from "../footer";

class Home extends React.Component<RouteComponentProps<MatchProps>> {

    componentDidMount() {
        Waves.attach('.'+bs.btn+':not(.'+bs["btn-flat"]+'), .'+bs["btn-floating"], ['waves-light']);
        Waves.attach('.'+bs["btn-flat"], ['waves-effect']);
        Waves.init();
        jarallax(document.querySelectorAll('.jarallax'));
    }

    render() {
            let lang = this.props.match.params.lang;
            return (
                <div>
                    <div className = {cx(homeStyle.jarallax, homeStyle.view) + " jarallax"} data-jarallax='{"speed": 0.2}'>
                        <div className = {cx(homeStyle.mask, homeStyle["rgba-black-light"])} >
                            <div className = {cx(bs.container, bs["h-100"], bs["d-flex"], bs["justify-content-center"], bs["align-items-center"])} >
                                <div className = {cx(bs.row, bs["pt-3"], bs["mt-3"])} >
                                    <div className = {cx(bs["col-md-12"])} >
                                        <div className = {cx(bs["text-center"])} >
                                            <h1 className = {cx(bs["text-uppercase"], bs["font-weight-bold"], bs["mb-3"])} style={{color: "white"}} >
                                                <strong>{_T(lang,"Welcome to AS139589")}</strong></h1>
                                            <hr className={cx(bs["hr-light"], bs["mt-4"])}/>
                                            <Link className={cx(bs.btn, bs["btn-light"], bs["mr-2"], "white")} role="button" to="/en/getConnected">{_T(lang,"Get Connected")}</Link>
                                            <Link className={cx(bs.btn, bs["btn-light"], "white")} role="button" to="/en/about">{_T(lang,"About")}</Link>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <main>
                        <div className={cx(bs.container, bs["mt-5"], bs["pt-3"], bs["pb-3"])}>
                            {lang === "zh_CN" &&
                            <div>
                                <h4>简介</h4>
                                <p>本网站包含有关<a href="https://www.gtdev.org">GTDev</a>运营的GTDev Network（AS139589）的信息。 </p>
                                <p>我们目前有三个接入点，一个主交换机在日本东京，我们在中国北京、德国法兰克福都有扩展交换机。</p>
                                <p>我们在每个接入点之间使用OpenVPN和ZeroTier隧道来建立2层连接。</p>
                                <h4>互联</h4>
                                <p>我们的互联政策是开放的。 您可以通过我们共同的互联网交换中心或通过隧道与我们互联。</p>
                                <h4>费用是多少？</h4>
                                <p>目前，与GTDev网络的互联是免费的，但是我们非常感谢任何形式的捐款以保持基础设施的运行。</p>
                                <p>PeeringDB: <a href="https://peeringdb.com/net/20634">https://peeringdb.com/net/20634</a></p>
                                <h4>如何加入？</h4>
                                <p>我们欢迎拥有公共资源（ASN和IPv6）的任何人加入我们的网络，以获得BGP和互联网路由技术的经验。</p>
                                <p>要先开始使用，请查看我们的<Link to="/zh/getConnected">连接页面</Link>。</p>
                            </div>
                            }
                            {lang === "en" &&
                            <div>
                                <h4>Introduction</h4>
                                <p>This website contains information about the GTDev Network (AS139589) operated by <a href="https://www.gtdev.org">GTDev</a>.</p>
                                <p>We have three POPs; one primary switch is in Tokyo Japan and we have extension switches in Beijing China, and Frankfurt Germany.</p>
                                <p>We use OpenVPN and ZeroTier tunnels between each POPs to establish layer 2 connectivity.</p>
                                <h4>Peering</h4>
                                <p>We have an open peering policy. You can peer with us through Internet eXchanges that we have in common, or via tunnels.</p>
                                <p>PeeringDB: <a href="https://peeringdb.com/net/20634">https://peeringdb.com/net/20634</a></p>
                                <h4>How much does it cost?</h4>
                                <p>Currently, peering with GTDev Network is free, although we do appreciate any donations to keep the infrastructure running.</p>
                                <h4>How do I join?</h4>
                                <p>We welcome anyone who holds public resources (ASN and IPv6) to join our network for the purpose of gaining experience with BGP and Internet routing technology.</p>
                                <p>To get started first, please view our <Link to="/en/getConnected">getting connected page</Link>.</p>
                            </div>
                            }
                        </div>
                    </main>
                    <Footer lang={lang}/>
                </div>
            )
    }
}

export default withRouter(Home);